// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.deal(address(c), 1 ether);
        vm.prank(caller);
        (bool ok, ) = address(c).call(abi.encodeWithSelector(SimpleWallet.withdrawAll.selector));
        if (ok) {
            assertEq(caller, c.owner());
        }
    }
}
